import csv
import glob

files = sorted(glob.glob("data/*.csv"))

with open("all.csv", "w", newline="") as out:
    writer = csv.writer(out)
    header_written = False
    for fname in files:
        with open(fname, newline="") as f:
            reader = csv.reader(f)
            for i, row in enumerate(reader):
                if i == 0:
                    if not header_written:
                        writer.writerow(row)
                        header_written = True
                else:
                    writer.writerow(row)

