"""Read events.jsonl, remove duplicate events sharing an event_id, write deduped.jsonl."""

import json


def main() -> None:
    seen: set[str] = set()
    deduped: list[str] = []

    with open("events.jsonl") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid is None:
                # Lines without an event_id are kept as-is
                deduped.append(line)
            elif eid in seen:
                continue
            else:
                seen.add(eid)
                deduped.append(line)

    with open("deduped.jsonl", "w") as f:
        for line in deduped:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

