import json


def load(path):
    with open(path, encoding='utf-8') as handle:
        return [json.loads(line) for line in handle if line.strip()]


def dedupe(rows):
    seen = {}
    for row in rows:
        eid = row.get('event_id')
        if eid is not None and eid not in seen:
            seen[eid] = row
    return list(seen.values())


def main():
    rows = load('events.jsonl')
    deduped = dedupe(rows)
    with open('deduped.jsonl', 'w', encoding='utf-8') as handle:
        for row in deduped:
            handle.write(json.dumps(row, ensure_ascii=False) + '\n')
    print(f'read {len(rows)} events, wrote {len(deduped)} unique events')


if __name__ == '__main__':
    main()

