import json


def main():
    seen = set()
    out = []
    with open('events.jsonl', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            eid = obj.get('event_id')
            if eid and eid in seen:
                continue
            seen.add(eid)
            out.append(obj)

    with open('deduped.jsonl', 'w', encoding='utf-8') as f:
        for obj in out:
            f.write(json.dumps(obj, ensure_ascii=False) + '\n')


if __name__ == '__main__':
    main()

