"""Read events.jsonl, remove events with duplicate event_id, write deduped.jsonl."""

import json


def main():
    seen = set()
    with open("events.jsonl", encoding="utf-8") as infile, \
         open("deduped.jsonl", "w", encoding="utf-8") as outfile:
        for line in infile:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid not in seen:
                seen.add(eid)
                outfile.write(line + "\n")


if __name__ == "__main__":
    main()

