#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_FILE = Path("manifest.json")


def file_digest(path: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    for path in sorted(RELEASE_DIR.rglob("*")):
        if not path.is_file():
            continue
        # Use forward-slash paths relative to the repository root
        rel = str(path.as_posix())
        manifest[rel] = file_digest(path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"wrote {MANIFEST_FILE} with {len(manifest)} entries")


if __name__ == "__main__":
    main()

