"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return hex SHA-256 digest of file contents."""
    h = hashlib.sha256()
    h.update(path.read_bytes())
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} not found")
        raise SystemExit(1)

    manifest = {}
    # Collect and sort for deterministic output
    files = sorted(RELEASE_DIR.rglob("*"), key=lambda p: p.relative_to(RELEASE_DIR).as_posix())
    for path in files:
        if path.is_file():
            rel = path.relative_to(RELEASE_DIR).as_posix()
            manifest[rel] = sha256_digest(path)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

