#!/usr/bin/env python3
"""List report files under reports/ in report order (by numeric suffix)."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")

def report_sort_key(filename):
    """Extract the numeric part from report-N.txt for sorting."""
    match = re.search(r'report-(\d+)\.txt$', filename)
    if match:
        return int(match.group(1))
    return 0

def main():
    try:
        files = [f for f in os.listdir(REPORTS_DIR) if os.path.isfile(os.path.join(REPORTS_DIR, f))]
    except FileNotFoundError:
        print("reports/ directory not found.")
        return

    files.sort(key=report_sort_key)
    for f in files:
        print(f)

if __name__ == "__main__":
    main()
