import os
import re


def report_files(reports_dir: str = "reports") -> list[str]:
    """Return report filenames in numeric order."""
    pattern = re.compile(r"^report-(\d+)\.txt$")
    files = []
    for name in os.listdir(reports_dir):
        m = pattern.match(name)
        if m:
            files.append((int(m.group(1)), name))
    files.sort(key=lambda x: x[0])
    return [name for _, name in files]


def main() -> None:
    for name in report_files():
        print(name)


if __name__ == "__main__":
    main()

