#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_key(filename: str) -> int:
    """Extract the numeric suffix from a report filename for sorting."""
    match = re.search(r"report-(\d+)\.txt$", filename)
    if match:
        return int(match.group(1))
    return -1


def main() -> None:
    try:
        filenames = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: '{REPORTS_DIR}' directory not found", file=__import__("sys").stderr)
        raise SystemExit(1)

    # Filter to only report files and sort numerically
    report_files = [f for f in filenames if re.match(r"report-\d+\.txt$", f)]
    report_files.sort(key=report_key)

    for f in report_files:
        print(f)


if __name__ == "__main__":
    main()

