"""Print nightly report file names, one per line, in report order."""

import re
from pathlib import Path

_REPORT = re.compile(r"^report-(\d+)\.txt$")


def _sort_key(path):
    """Report order is numeric: report-2.txt comes before report-10.txt."""
    match = _REPORT.fullmatch(path.name)
    if match:
        return (0, int(match.group(1)), path.name)
    return (1, float("inf"), path.name)


def main():
    reports_dir = Path(__file__).resolve().parent / "reports"
    for path in sorted(reports_dir.iterdir(), key=_sort_key):
        if path.is_file():
            print(path.name)


if __name__ == "__main__":
    main()

