#!/usr/bin/env python3
"""List reports/ files in report order (sorted by numeric suffix)."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(__file__), "reports")


def report_key(name: str) -> int:
    """Extract the integer suffix from a report filename for ordering."""
    m = re.search(r"report-(\d+)", name)
    if m is None:
        return float("inf")  # non-matching files sort last
    return int(m.group(1))


def main() -> None:
    try:
        names = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return  # no reports directory yet

    names.sort(key=report_key)
    for name in names:
        print(name)


if __name__ == "__main__":
    main()
