"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
import datetime


def parse_ts(line: str) -> datetime.datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS ' prefix from a log line and return a UTC datetime."""
    if len(line) < 19:
        return None
    try:
        return datetime.datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=datetime.timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.datetime.fromtimestamp(as_of, tz=datetime.timezone.utc) - datetime.timedelta(
        days=7
    )

    with open("app.log", "r") as f:
        lines = f.readlines()

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        # Preserve empty lines and unparseable lines as-is; keep them in app.log
        ts = parse_ts(line)
        if ts is None:
            keep.append(line)
        elif ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    if archive:
        with open("archive.log", "a") as f:
            f.writelines(archive)

    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

