import sys
from datetime import datetime, timezone

def parse_line(line):
    """Parse a log line into (unix_timestamp, raw_line) or None if unparseable."""
    line = line.rstrip('\n')
    if not line:
        return None
    # Expected format: "YYYY-MM-DD HH:MM:SS message"
    if len(line) < 19 or line[10] != ' ' or line[4] != '-' or line[7] != '-':
        return None
    ts_str = line[:19]
    try:
        dt = datetime.strptime(ts_str, '%Y-%m-%d %H:%M:%S')
        dt = dt.replace(tzinfo=timezone.utc)
        return (dt.timestamp(), line)
    except ValueError:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400

    # Read all lines from app.log
    try:
        with open('app.log', 'r') as f:
            raw_lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    keep_lines = []
    archive_lines = []

    for raw_line in raw_lines:
        result = parse_line(raw_line)
        if result is None:
            # Unparseable line — keep it in app.log by default
            keep_lines.append(raw_line)
        else:
            ts, full_line = result
            if ts < cutoff:
                archive_lines.append(full_line + '\n')
            else:
                keep_lines.append(raw_line)

    # Append archive entries to archive.log
    if archive_lines:
        with open('archive.log', 'a') as f:
            f.writelines(archive_lines)

    # Rewrite app.log with kept entries
    with open('app.log', 'w') as f:
        f.writelines(keep_lines)

if __name__ == '__main__':
    main()

